INFO_MSGS = deque(maxlen=50)
_INFO_ASK = {}                       # ip -> times of questions (at most 5 per hour)


def info_html():
    import gzip as _gz, base64 as _b64
    h = _gz.decompress(_b64.b64decode(INFO_HTML_GZ)).decode("utf-8")
    inj = INFO_INJECT.replace("__MAIL__", json.dumps(str(CFG.get("info_mail") or "")))
    return h.replace("</body>", inj + "</body>", 1) if "</body>" in h else h + inj


INFO_INJECT = r"""<script>
// shown by MoveEye itself (2.95.52): the form sends the question straight to the owner (push message)
(function () {
  const M = __MAIL__, f = document.getElementById("ask"), note = document.getElementById("note");
  const T = {de: {go: "Senden", ok: "✓ Danke! Die Nachricht ist angekommen.", err: "Senden ging nicht - bitte später nochmals.", many: "Zu viele Nachrichten - bitte später nochmals."},
             en: {go: "Send", ok: "✓ Thank you! The message has arrived.", err: "Sending failed - please try again later.", many: "Too many messages - please try again later."},
             fr: {go: "Envoyer", ok: "✓ Merci\u202f! Le message est bien arrivé.", err: "L'envoi n'a pas marché - réessaie plus tard.", many: "Trop de messages - réessaie plus tard."},
             it: {go: "Invia", ok: "✓ Grazie! Il messaggio è arrivato.", err: "Invio non riuscito - riprova più tardi.", many: "Troppi messaggi - riprova più tardi."}};
  const L = () => T[document.documentElement.lang] || T.en;
  const addr = document.querySelector(".addr");
  if (M) { const c = document.getElementById("mail"); if (c) c.textContent = M; if (addr) addr.hidden = false;
    document.addEventListener("click", ev => { if (!ev.target.closest || !ev.target.closest("#copy")) return; ev.stopPropagation(); try { navigator.clipboard.writeText(M); note.textContent = "✓"; } catch (e) {} }, true); }
  else if (addr) addr.hidden = true;
  const btn = f && f.querySelector("button[type=submit]");
  const fix = () => { if (btn) btn.textContent = L().go; };
  fix(); document.querySelectorAll(".langs button[data-lang]").forEach(b => b.addEventListener("click", () => setTimeout(fix, 0)));
  if (f) document.addEventListener("submit", async ev => {
    if (ev.target !== f) return;
    ev.preventDefault(); ev.stopPropagation();
    const msg = document.getElementById("f-msg").value.trim(); if (!msg) { document.getElementById("f-msg").focus(); return; }
    const sel = document.getElementById("f-topic");
    const pk = document.getElementById("f-pack"), pr = document.getElementById("f-pack-row");
    const pack = pk && pr && !pr.hidden ? pk.selectedOptions[0].textContent : "";   // 3.45: package chosen for an order
    const d = {name: document.getElementById("f-name").value.trim(), topic: sel.selectedOptions[0].textContent, msg: (pack ? "[" + pack + "] " : "") + msg};
    if (btn) btn.disabled = true;
    try { const r = await fetch("/info/ask", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(d)});
      note.textContent = r.ok ? L().ok : (r.status === 429 ? L().many : L().err); if (r.ok) document.getElementById("f-msg").value = ""; }
    catch (e) { note.textContent = L().err; }
    if (btn) btn.disabled = false;
  }, true);
})();
</script>"""


